design_system.text:
{
  "base": {
    "$type": "color",
    "$description": "基礎の層。色の値はここにだけ書く",
    "teal": {
      "100": {
        "$value": {
          "colorSpace": "srgb",
          "components": [
            0.8353,
            0.902,
            0.8902
          ],
          "hex": "#d5e6e3"
        }
      },
      "300": {
        "$value": {
          "colorSpace": "srgb",
          "components": [
            0.4235,
            0.7882,
            0.7216
          ],
          "hex": "#6cc9b8"
        }
      },
      "700": {
        "$value": {
          "colorSpace": "srgb",
          "components": [
            0.051,
            0.3608,
            0.3333
          ],
          "hex": "#0d5c55"
        }
      },
      "900": {
        "$value": {
          "colorSpace": "srgb",
          "components": [
            0.0902,
            0.2,
            0.1882
          ],
          "hex": "#173330"
        }
      }
    },
    "rose": {
      "100": {
        "$value": {
          "colorSpace": "srgb",
          "components": [
            0.9647,
            0.8784,
            0.8745
          ],
          "hex": "#f6e0df"
        }
      },
      "300": {
        "$value": {
          "colorSpace": "srgb",
          "components": [
            0.9412,
            0.6392,
            0.6275
          ],
          "hex": "#f0a3a0"
        }
      },
      "700": {
        "$value": {
          "colorSpace": "srgb",
          "components": [
            0.6392,
            0.149,
            0.1647
          ],
          "hex": "#a3262a"
        }
      },
      "900": {
        "$value": {
          "colorSpace": "srgb",
          "components": [
            0.2275,
            0.1098,
            0.1137
          ],
          "hex": "#3a1c1d"
        }
      }
    }
  },
  "color": {
    "$type": "color",
    "$description": "意味の層（明）。値は基礎の層を指す",
    "surface": {
      "block": {
        "$value": "{base.paper.000}",
        "$description": "節の枠の面"
      },
      "literal": {
        "$value": "{base.paper.100}",
        "$description": "コード ・ 差分 ・ フォルダ構成 ・ 実行例の面（字面をそのまま見せる所）"
      },
      "added": {
        "$value": "{base.teal.100}",
        "$description": "差分の足した行の面"
      },
      "removed": {
        "$value": "{base.rose.100}",
        "$description": "差分の消した行の面"
      }
    },
    "text": {
      "body": {
        "$value": "{base.ink.900}",
        "$description": "本文"
      },
      "added": {
        "$value": "{base.teal.700}",
        "$description": "差分の + の記号"
      },
      "removed": {
        "$value": "{base.rose.700}",
        "$description": "差分の − の記号 ・ 0 以外の終了コード"
      }
    },
    "syntax": {
      "keyword": {
        "$value": "{base.teal.700}",
        "$description": "コードのキーワード"
      }
    },
    "mark": {
      "added": {
        "$value": "{base.teal.700}",
        "$description": "フォルダ構成の「足す」の印の面"
      }
    }
  },
  "font": {
    "$type": "fontFamily",
    "body": {
      "$value": [
        "Zen Kaku Gothic New",
        "system-ui",
        "sans-serif"
      ]
    },
    "heading": {
      "$value": [
        "Shippori Mincho",
        "serif"
      ]
    },
    "literal": {
      "$value": [
        "JetBrains Mono",
        "Zen Kaku Gothic New",
        "monospace"
      ],
      "$description": "字面を見せる所だけに使う。日本語は Zen Kaku Gothic New で描く"
    }
  },
  "size": {
    "$type": "dimension",
    "body": {
      "$value": {
        "value": 15,
        "unit": "px"
      }
    },
    "literal": {
      "$value": {
        "value": 13,
        "unit": "px"
      }
    },
    "space-3": {
      "$value": {
        "value": 0.45,
        "unit": "rem"
      }
    },
    "space-5": {
      "$value": {
        "value": 0.7,
        "unit": "rem"
      }
    },
    "space-7": {
      "$value": {
        "value": 1.2,
        "unit": "rem"
      }
    },
    "radius": {
      "$value": {
        "value": 0.6,
        "unit": "rem"
      }
    },
    "line-hair": {
      "$value": {
        "value": 1,
        "unit": "px"
      }
    },
    "line-solid": {
      "$value": {
        "value": 2,
        "unit": "px"
      }
    },
    "line-accent": {
      "$value": {
        "value": 3,
        "unit": "px"
      }
    }
  },
  "type": {
    "$type": "typography",
    "body": {
      "$value": {
        "fontFamily": "{font.body}",
        "fontSize": "{size.body}",
        "fontWeight": 400,
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        },
        "lineHeight": 1.85
      }
    },
    "literal": {
      "$value": {
        "fontFamily": "{font.literal}",
        "fontSize": "{size.literal}",
        "fontWeight": 400,
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        },
        "lineHeight": 1.6
      }
    }
  },
  "$extensions": {
    "works.daidaiiro.contrast": [
      {
        "foreground": "color.text.added",
        "background": "color.surface.added",
        "use": "text"
      },
      {
        "foreground": "color.text.body",
        "background": "color.surface.added",
        "use": "text"
      },
      {
        "foreground": "color.text.removed",
        "background": "color.surface.removed",
        "use": "text"
      },
      {
        "foreground": "color.text.body",
        "background": "color.surface.removed",
        "use": "text"
      }
    ]
  }
}
